#!/bin/bash\n\n# ============================================\n# AI Creator MVP - Start Public Servers\n# ============================================\n\necho \"🚀 Starting AI Creator MVP Public Servers\"\necho \"========================================\"\n\n# Colors\nGREEN='\\033[0;32m'\nBLUE='\\033[0;34m'\nYELLOW='\\033[1;33m'\nRED='\\033[0;31m'\nNC='\\033[0m' # No Color\n\n# Project root\nPROJECT_ROOT=\"/home/ubuntu/ai-creator-mvp\"\n\necho -e \"${BLUE}📁 Project Root: $PROJECT_ROOT${NC}\"\n\n# ============================================\n# 1. Start Backend Server (Public)\n# ============================================\n\necho -e \"${YELLOW}\\n1️⃣  Starting Backend Server (Public)...${NC}\"\necho \"   Location: $PROJECT_ROOT/backend\"\necho \"   Host: 0.0.0.0\"\necho \"   Port: 3000\"\n\ncd \"$PROJECT_ROOT/backend\"\n\n# Check if node_modules exists\nif [ ! -d \"node_modules\" ]; then\n    echo -e \"${YELLOW}   Installing dependencies...${NC}\"\n    npm install > /dev/null 2>&1\nfi\n\n# Start backend in background using public server\necho -e \"${GREEN}   ✅ Backend starting on 0.0.0.0:3000${NC}\"\nnode src/index-public.js > \"$PROJECT_ROOT/backend-public.log\" 2>&1 &\nBACKEND_PID=$!\necho \"   PID: $BACKEND_PID\"\n\n# Wait for backend to start\nsleep 2\n\nif ps -p $BACKEND_PID > /dev/null; then\n    echo -e \"${GREEN}   ✅ Backend is running${NC}\"\nelse\n    echo -e \"${RED}   ❌ Backend failed to start${NC}\"\n    echo \"   Check: $PROJECT_ROOT/backend-public.log\"\nfi\n\n# ============================================\n# 2. Start Admin Dashboard (Public)\n# ============================================\n\necho -e \"${YELLOW}\\n2️⃣  Starting Admin Dashboard (Public)...${NC}\"\necho \"   Location: $PROJECT_ROOT/admin_dashboard\"\necho \"   Host: 0.0.0.0\"\necho \"   Port: 3001\"\n\ncd \"$PROJECT_ROOT/admin_dashboard\"\n\n# Check if node_modules exists\nif [ ! -d \"node_modules\" ]; then\n    echo -e \"${YELLOW}   Installing dependencies...${NC}\"\n    npm install > /dev/null 2>&1\nfi\n\n# Install express-session if not present\nif ! npm list express-session > /dev/null 2>&1; then\n    echo -e \"${YELLOW}   Installing express-session...${NC}\"\n    npm install express-session > /dev/null 2>&1\nfi\n\n# Start admin dashboard in background using public server\necho -e \"${GREEN}   ✅ Admin Dashboard starting on 0.0.0.0:3001${NC}\"\nnode server-public.js > \"$PROJECT_ROOT/admin-public.log\" 2>&1 &\nADMIN_PID=$!\necho \"   PID: $ADMIN_PID\"\n\n# Wait for admin to start\nsleep 2\n\nif ps -p $ADMIN_PID > /dev/null; then\n    echo -e \"${GREEN}   ✅ Admin Dashboard is running${NC}\"\nelse\n    echo -e \"${RED}   ❌ Admin Dashboard failed to start${NC}\"\n    echo \"   Check: $PROJECT_ROOT/admin-public.log\"\nfi\n\n# ============================================\n# 3. Display Public URLs and Credentials\n# ============================================\n\necho -e \"${GREEN}\\n✅ All servers are running!${NC}\"\necho \"\"\necho \"========================================\"\necho -e \"${BLUE}📊 ADMIN DASHBOARD (PUBLIC)${NC}\"\necho \"========================================\"\necho -e \"${GREEN}URL:${NC} https://3001-iquo2hb07nd93l0roye51-1cdaf514.sg1.manus.computer\"\necho -e \"${GREEN}Email:${NC} admin@aicreator.app\"\necho -e \"${GREEN}Password:${NC} Admin@123456\"\necho \"\"\necho \"========================================\"\necho -e \"${BLUE}🔌 BACKEND API (PUBLIC)${NC}\"\necho \"========================================\"\necho -e \"${GREEN}Base URL:${NC} https://3000-iquo2hb07nd93l0roye51-1cdaf514.sg1.manus.computer\"\necho -e \"${GREEN}Health Check:${NC} /health\"\necho -e \"${GREEN}API Status:${NC} /api/status\"\necho \"\"\necho \"========================================\"\necho -e \"${BLUE}📱 FLUTTER APP CONFIG${NC}\"\necho \"========================================\"\necho -e \"${GREEN}API_BASE_URL:${NC}\"\necho \"https://3000-iquo2hb07nd93l0roye51-1cdaf514.sg1.manus.computer\"\necho \"\"\necho \"========================================\"\necho -e \"${BLUE}📝 LOGS${NC}\"\necho \"========================================\"\necho -e \"${GREEN}Backend Log:${NC} $PROJECT_ROOT/backend-public.log\"\necho -e \"${GREEN}Admin Log:${NC} $PROJECT_ROOT/admin-public.log\"\necho \"\"\necho \"View logs with:\"\necho \"  tail -f $PROJECT_ROOT/backend-public.log\"\necho \"  tail -f $PROJECT_ROOT/admin-public.log\"\necho \"\"\necho \"========================================\"\necho -e \"${BLUE}🛑 STOP SERVERS${NC}\"\necho \"========================================\"\necho \"To stop all servers, run:\"\necho \"  kill $BACKEND_PID $ADMIN_PID\"\necho \"\"\necho \"Or use:\"\necho \"  pkill -f 'index-public.js' (Backend)\"\necho \"  pkill -f 'server-public.js' (Admin)\"\necho \"\"\necho \"========================================\"\necho -e \"${GREEN}🎉 Ready to test from mobile!${NC}\"\necho \"========================================\"\necho \"\"\necho \"⏱️  Servers will keep running until you press Ctrl+C\"\necho \"\"\n\n# Trap Ctrl+C to kill child processes\ntrap \"echo -e '\\n${YELLOW}Stopping servers...${NC}'; kill $BACKEND_PID $ADMIN_PID 2>/dev/null; exit\" INT\n\n# Wait for all background processes\nwait\n
